struct Stack {
    head: [Int]?
}

impl Stack {
    // Beginner form: one call, the place is never empty.
    fn pop_all(&self) -> [Int]? {
        replace(&self.head, None)
    }

    // Manual form: the same moves, written out.
    fn pop_all_by_hand(&self) -> [Int]? {
        old :: ^self.head
        self.head = None
        old
    }
}

fn flip(d: &Deque) {
    swap(&d.front, &d.back)
}

fn flip_by_hand(d: &Deque) {
    t :: ^d.front
    d.front = ^d.back
    d.back = ^t
}

enum Conn {
    Idle
    Open(buf: [U8])
}

// next may stop (it is not marked -[!Panic]>).
fn next(c: ^Conn) -> Conn {
    if ^c == {
        .Idle -> .Open(buf: [U8]{})
        .Open(buf) -> .Idle
    }
}

struct Client {
    conn: Conn
}

impl Client {
    fn step(&self) {
        // The place holds a stand-in while next runs.
        old :: replace(&self.conn, .Idle)
